import { BaseException } from '@game-studio/exceptions';
import { Locale } from '../../types';

export interface IExceptionData {
    propertyName: string;
}

export class MissingPropertyException extends BaseException<IExceptionData> {
    constructor(propertyName: string) {
        super('MapAndValidate.MissingPropertyException', `Automapping failed. Source data missing property '${propertyName}'`, {
            propertyName
        });
    }

    public localise(locale: Locale): void {
        this.buttonText = this.getButtonText(locale);
        this.displayMessage = this.getGenericErrorMessage(locale);
    }
}
